SELECT CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 80 THEN 'mid' ELSE 'low' END AS unit_price_bucket, SUM(quantity) AS total_quantity, SUM(SUM(quantity)) OVER (ORDER BY CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 80 THEN 'mid' ELSE 'low' END) AS cumulative_quantity FROM order_items GROUP BY CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 80 THEN 'mid' ELSE 'low' END ORDER BY total_quantity
